def name_operands(region,function_address,operation):
    if region=='Action' and function_address==0xDD23:
        for name,address in (('FaceGate',0x8D5A),):operation=operation.replace('(#'+format(address,'04X')+')','(@ActionPacketRendererState.'+name+')')
        for name,address in (('FirstPoint',0x8D2A),('SecondPoint',0x8D2C),('PixelOpcode',0x8D4E),('MaskOffset',0xDE0F)):
            operation=operation.replace('(#'+format(address,'04X')+')','(@ActionLineRasterState.'+name+')')
        for old,new in (('(#8D2D)','(@ActionLineRasterState.SecondPoint+1)'),('(#D560)','(@ActionPolygonPreparationState.Mode)'),
            ('(#9BA3)','(@ActionClipIntersectionsState.OutputSize)'),('CALL #DFB6','CALL @Action.CheckFaceOrientation.Entry'),
            ('CALL #D511','CALL @Action.PreparePolygonFill.Entry'),('CALL #DDF0','CALL @Action.DrawLinearLine.Entry'),
            ('JP #DD23','JP @Action.RenderInsideRecords.Entry'),('AND #0F','AND @ActionPacketRendererConst.CountMask'),
            ('AND #07','AND @ActionPacketRendererConst.MaterialMask'),('AND #30','AND @ActionPacketRendererConst.LineModeMask'),
            ('BIT 6, (HL)','BIT @ActionPacketRendererConst.AttachBit, (HL)'),('LD DE, #9000','LD DE, @ActionPolygonPreparationState.Vertices'),
            ('LD B, #8E','LD B, @ActionPacketRendererConst.PointPage'),('LD D, #8E','LD D, @ActionPacketRendererConst.PointPage'),
            ('LD DE, #38A9','LD DE, @ActionPacketRendererConst.XorModeWord'),('LD DE, #30A1','LD DE, @ActionPacketRendererConst.AndModeWord'),
            ('LD DE, #38B1','LD DE, @ActionPacketRendererConst.OrModeWord'),('LD A, #18','LD A, @ActionLineRasterConst.ClearOffset'),
            ('LD A, #10','LD A, @ActionLineRasterConst.SetOffset'),('CP #10','CP @ActionPacketRendererConst.OrSelector')):
            operation=operation.replace(old,new)
    return operation


def constants():
    lines=['','                module ActionPacketRendererConst']
    for name,value,note in (('CountMask',15,'число вершин в младшей тетраде'),('MaterialMask',7,'числовое поле материала грани после четырёх сдвигов'),
        ('LineModeMask',0x30,'числовое поле операции линии в разрядах 5..4'),('AttachBit',6,'бит связи линии с предыдущей ориентацией'),
        ('PointPage',0x8E,'страница исходных пятибайтовых проецированных точек'),('XorModeWord',0x38A9,'пара XOR C и JR C'),
        ('AndModeWord',0x30A1,'пара AND C и JR NC'),('OrModeWord',0x38B1,'пара OR C и JR C'),('OrSelector',0x10,'числовой селектор OR в исходном положении поля')):
        lines.append((name.ljust(16)+'equ #'+format(value,'04X' if value>255 else '02X')).ljust(80)+'; '+note)
    return '\n'.join(lines+['                endmodule',''])


